namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var allocations = new List<string>();
        int remaining = item.OnHand - item.Reserved;

        if (remaining <= 0)
            return allocations;

        foreach (var zone in warehouse.Zones)
        {
            if (!IsUsable(zone))
                continue;

            int quantity = CalculateQuantity(remaining, zone.Capacity);
            if (quantity <= 0)
                continue;

            allocations.Add($"{zone.Name}:{quantity}");
            remaining -= quantity;

            if (remaining <= 0)
                break;
        }

        AddOverflowIfNeeded(allocations, remaining);
        return allocations;
    }

    private static bool IsUsable(Zone zone) =>
        zone.Capacity > 0 && !string.IsNullOrEmpty(zone.Name);

    private static int CalculateQuantity(int remaining, int capacity)
    {
        if (remaining > capacity)
            return capacity;

        return remaining > capacity / 2 ? remaining - 1 : remaining;
    }

    private static void AddOverflowIfNeeded(List<string> allocations, int remaining)
    {
        if (remaining > 0)
            allocations.Add($"OVERFLOW:{remaining}");
    }
}
